/**
 *
 * MenuCheckboxItem is a checkable menu item managed by useCheckbox.
 *
 * [Live Demo](https://www.primereact.org/menu/)
 *
 * @module MenuCheckboxItem
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseCheckboxChangeEvent, UseCheckboxExposes, UseCheckboxProps } from '@primereact/types/headless/checkbox';
import * as React from 'react';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { MenuPortalInstance } from './MenuPortal.types';
import type { MenuItemSelectEvent, MenuRootInstance } from './MenuRoot.types';
import type { MenuSubmenuInstance } from './MenuSubmenu.types';
/**
 * Defines passthrough(pt) options type in MenuCheckboxItem component.
 */
export type MenuCheckboxItemPassThroughType<E> = PassThroughType<MenuCheckboxItemInstance, E>;
/**
 * Defines passthrough(pt) options of MenuCheckboxItem component.
 */
export interface MenuCheckboxItemPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: MenuCheckboxItemPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Event fired when the checkbox item's checked state changes.
 */
export interface MenuCheckboxItemCheckedChangeEvent extends UseCheckboxChangeEvent<React.SyntheticEvent> {
}
/**
 * Defines valid properties in MenuCheckboxItem component.
 */
export interface MenuCheckboxItemProps extends BaseComponentProps<MenuCheckboxItemInstance, Omit<UseCheckboxProps, 'onCheckedChange'>, MenuCheckboxItemPassThrough> {
    /**
     * When present, it specifies that the item should be disabled.
     */
    disabled?: boolean | undefined;
    /**
     * Semantic value that uniquely identifies this item within the menu and is forwarded to useCheckbox.
     * Used to generate a deterministic DOM id. When not provided, auto-generated.
     */
    value?: unknown | undefined;
    /**
     * Whether the menu should close when this checkbox item is toggled.
     * Defaults to `false` for checkbox items so toggling the value keeps the
     * menu open; set explicitly to `true` to close on each toggle.
     * @default false
     */
    closeOnSelect?: boolean | undefined;
    /**
     * Callback fired when the item is activated. Calling
     * `event.preventDefault()` keeps the menu open regardless of
     * `closeOnSelect`.
     */
    onSelect?: (event: MenuItemSelectEvent) => void;
    /**
     * Callback fired when the checkbox item's checked state changes.
     */
    onCheckedChange?: (event: MenuCheckboxItemCheckedChangeEvent) => void;
}
/**
 * Defines valid state in MenuCheckboxItem component.
 */
export interface MenuCheckboxItemState {
}
/**
 * Defines the methods and properties exposed by MenuCheckboxItem component.
 * @extends UseCheckboxExposes
 */
export interface MenuCheckboxItemExposes extends UseCheckboxExposes {
    /**
     * Instance of the Menu component.
     */
    menu: MenuRootInstance | undefined | null;
    /**
     * Instance of the MenuSubmenu component.
     */
    submenu: MenuSubmenuInstance | undefined | null;
    /**
     * Instance of the MenuPortal component.
     */
    portal: MenuPortalInstance | undefined | null;
    /**
     * ID of the item element.
     */
    itemId: string | undefined;
    /**
     * Whether the item is focused or not.
     */
    focused: boolean;
    /**
     * Whether the item is disabled or not.
     */
    isDisabled: boolean;
    /**
     * Whether the item is checked or not.
     */
    checked: boolean;
}
/**
 * Instance of MenuCheckboxItem component.
 */
export type MenuCheckboxItemInstance = ComponentInstance<MenuCheckboxItemProps, MenuCheckboxItemState, MenuCheckboxItemExposes>;
